mapper.select:
SELECT c.*, a.code AS account_code, a.name AS account_name, CASE WHEN THEN 1 ELSE 0 END AS used, (SELECT COUNT(*) FROM fin_bank_opening_item i WHERE i.cash_account_id = c.id) AS opening_item_count FROM fin_cash_account c LEFT JOIN fin_account a ON a.id = c.account_id
AND c.id = #{id}
ORDER BY c.sort, a.code, c.id
